window.ApplicationDetails=(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>n==null?'待确认':'US$'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
 const list=items=>'<ul class="detail-list">'+(items||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>';
 const link=(url,title)=>url?'<button class="plan-button compact" data-detail-url="'+esc(url)+'">'+esc(title)+' ↗</button>':'';
 const card=(title,body)=>'<section class="simple-detail-card"><h3>'+title+'</h3>'+body+'</section>';
 const pair=(label,value)=>'<div class="detail-pair"><span>'+esc(label)+'</span><p>'+esc(value||'待确认')+'</p></div>';
 function waiverMarkup(w){if(!w)return '';return card('申请费减免', '<p>'+esc(w.basis)+'</p><div class="detail-pairs">'+pair('建议请求日期',w.recommendedDeadline)+pair('官网规则推算最晚',w.officialRequestDeadline)+pair('申请最终截止',w.finalApplicationDeadline)+'</div><p class="detail-muted">'+esc(w.officialRule)+'</p><p class="detail-muted">'+esc(w.noImpact)+'</p><details class="simple-detail-fold"><summary>查看减免材料与说明</summary>'+list(w.preparation)+'<p>'+esc(w.deadlineNote)+'</p></details>'+link(w.policyUrl,w.policyLabel||'官方减免政策'));}
 async function render(p,node,kind){
  if(!node||!p)return;const id=kind==='PhD'?'phd-'+p.id:p.id,a=kind==='PhD'?p.admissions:p,w=a?.waiver||p.waiver,finance=a?.finance,deadline=a?.deadline||w?.finalApplicationDeadline||'';
  node.dataset.detailId=id;
  node.classList.add('simple-detail-pane');node.innerHTML='<div class="empty-note">正在读取项目…</div>';
  const snapshot=await window.desktopAPI.getApplications();if(!document.contains(node)||node.dataset.detailId!==id)return;const entry=snapshot.items.find(i=>i.id===id);if(!entry)return;
  window.CompletionFinance.update(snapshot);
  const fee=entry.fee.overrideUsd??entry.feeUsd,net=entry.fee.waived?0:fee;
  const until=deadline?Math.round((Date.parse(deadline+'T00:00:00Z')-Date.parse(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Vancouver',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'T00:00:00Z'))/86400000):null;
  let body='';
  if(kind==='PhD'){
   body+='<div class="detail-metric-grid">'+[['引用量（约）',p.citations],['H-index（约）',p.hIndex],['i10-index（约）',p.i10Index],['匹配度',p.match]].map(([k,v])=>'<div><span>'+esc(k)+'</span><strong>'+esc(v||'—')+'</strong></div>').join('')+'</div>';
   body+=card('联络情况',pair('当前状态',p.state)+pair('教授积极程度',p.positivity)+pair('依据与备注',p.note));
   body+=card('研究方向','<div class="simple-chips">'+String(p.keywords||'').split(',').map(x=>'<span>'+esc(x.trim())+'</span>').join('')+'</div><p class="detail-muted">'+esc(p.school)+' · '+esc(p.department)+'</p>');
  }else body+=window.CompletionFinance.details(entry)+card('项目方向',pair('研究 / 课程方向',p.focus)+pair('GRE 政策',p.gre));
  if(a){body+='<div class="detail-two-columns">'+card('申请材料',list(kind==='PhD'?a.materials:a.requirements))+card('申请要求',a.hardThresholds||a.thresholds?list(a.hardThresholds||a.thresholds):'<p>'+esc(a.threshold)+'</p>')+'</div>';if(a.softThresholds)body+=card('竞争力参考',list(a.softThresholds)+'<p class="detail-muted">原助手中的准备建议，不代表官方录取最低线。</p>');}
  if(finance&&kind==='PhD'){body+=card(kind==='PhD'?'博士资助':'学费参考',kind==='PhD'?'<div class="detail-finance-value">'+(finance.stipendUsd!=null?money(finance.stipendUsd)+'<small> / 年 · 税前</small>':esc(finance.stipendText||'以 offer 为准'))+'</div>'+pair('学费与资助覆盖',finance.tuitionCoverage)+'<p class="detail-muted">'+esc(finance.stipendOriginal)+' '+esc(finance.stipendNote)+'</p>':'<div class="detail-finance-value">'+money(finance.tuitionUsd)+'</div><p>'+esc(finance.tuitionOriginal)+'</p><p class="detail-muted">'+esc(finance.tuitionNote)+'</p>');}
  if(entry.applicationPolicy)body+=card('同校申请规则','<p>'+esc(entry.applicationPolicy.summary)+'</p>'+link(entry.applicationPolicy.url,'官方申请限制'));const policy=entry.feeWaiver;if(policy){body+=card(policy.recommended?'建议waive':'申请费政策','<p>'+esc(policy.summary)+'</p><p class="detail-muted">'+esc(policy.steps)+'</p><p class="detail-muted">官网核查 '+esc(policy.checkedAt)+'</p>'+link(policy.url,'官方政策'));}if(w)body+='<details class="simple-detail-card simple-detail-fold"><summary>原助手减免准备建议 · '+esc(snapshot.snapshot)+'</summary>'+waiverMarkup(w)+'</details>';
  if(kind==='PhD')body+=card('邮件原文','<details id="email-fold" class="simple-detail-fold"><summary>查看 '+esc(p.emailFile||'联络证据')+'</summary><div id="email-content">'+(p.emailFile?'展开后读取原始邮件。':esc(p.note||'暂无原始邮件记录'))+'</div></details>');
  body+=card('官方入口','<div class="simple-detail-links">'+link(a?.applyUrl,'进入申请系统')+link(a?.programUrl,'项目官网')+'</div><p class="detail-muted">'+esc(a?.sourceLabel||'原 PhD 申请助手')+' · 数据快照 '+esc(snapshot.snapshot)+'</p>');
  if(kind==='PhD')body+='<details class="simple-detail-card simple-detail-fold"><summary>查看原始完整字段</summary><div class="detail-pairs">'+[['排序',p.order],['分类',p.category],['全球排名',p.rank],['学校',p.school],['院系',p.department],['研究关键词',p.keywords],['引用量',p.citations],['H-index',p.hIndex],['i10-index',p.i10Index],['匹配度',p.match],['当前状态',p.state],['积极程度',p.positivity],['备注',p.note]].map(([k,v])=>pair(k,v)).join('')+'</div></details>';
  node.innerHTML='<div class="simple-detail-page"><div class="simple-detail-heading"><p class="eyebrow">'+esc(kind)+' · '+esc(kind==='PhD'?p.schoolShort:p.university)+'</p><h1>'+esc(kind==='PhD'?p.name:p.program)+'</h1><p>'+esc(kind==='PhD'?p.school+' · '+p.department:p.university+' · '+p.focus)+'</p></div><div class="detail-overview-grid"><div class="simple-detail-card deadline-summary"><span>最终申请截止</span><strong>'+esc(deadline||'待公布')+'</strong><p>'+esc(until===null?'日期尚待确认':until<0?'已截止':until===0?'今天截止':'还剩 '+until+' 天')+'</p><small>'+esc(a?.deadlineContext||w?.finalDeadlineNote||'具体提交时刻以官网为准')+'</small></div><div class="simple-detail-card fee-summary"><span>预计申请费</span><strong>'+money(net)+'</strong><p>'+esc(entry.fee.waived?'已确认费用减免':fee===0?'项目申请费为零':'原始费用 '+money(entry.feeUsd))+'</p><small>'+esc(entry.feeOriginal||entry.feeNote)+'</small></div></div><div class="detail-selection"><label><input id="detail-selection" type="checkbox" '+(entry.selected?'checked':'')+'>加入我的申请计划</label><span>'+esc(entry.selected?(entry.calendar?.status==='synced'?'日历已同步':deadline?'待同步到日历':'截止日期待确认'):'未选择')+'</span><button class="plan-button compact" id="detail-budget">选择与预算</button></div>'+body+'</div>';
  node.querySelector('#detail-selection').onchange=async e=>{const r=await window.desktopAPI.saveApplication({id,selected:e.target.checked});if(r.ok===false){alert(r.error);return;}render(p,node,kind);};
  node.querySelector('#detail-budget').onclick=()=>window.ApplicationDetails.showPlan?.();
  node.querySelectorAll('[data-detail-url]').forEach(b=>b.onclick=()=>window.desktopAPI.openWebsite(b.dataset.detailUrl));
  const fold=node.querySelector('#email-fold');if(fold&&p.emailFile)fold.ontoggle=async()=>{if(!fold.open||fold.dataset.loaded)return;fold.dataset.loaded='true';const target=node.querySelector('#email-content');target.textContent='正在读取邮件…';try{const m=await window.desktopAPI.readEmail(p.emailFile);target.innerHTML='<div class="detail-email-meta">'+pair('主题',m.subject)+pair('日期',m.date)+pair('发件人',m.from)+pair('收件人',m.to)+'</div><pre class="detail-email-body">'+esc(m.text)+'</pre>';}catch(e){target.textContent=e.message;}};
 }
 return {professor:(p,node)=>render(p,node,'PhD'),master:(p,node)=>render(p,node,'MS')};
})();
